import type { PrimaryFamily, SubRole } from '../../src/engine/subRoles';

/**
 * Tabella di riferimento dei sotto-ruoli (Task 8): per i 40 Pokémon più usati di ogni formato del banco,
 * il set più comune (stats.json, ottobre 2026) e i sotto-ruoli che un giocatore Smogon gli darebbe.
 * Le attese vengono dalla lettura competitiva del set, NON dall'output del rilevatore.
 *
 * - `has`: sotto-ruoli che devono valere ≥ 0.5.
 * - `hasAny`: almeno uno di questi ≥ 0.5 (es. "attaccante, ma sweeper o wallbreaker è opinabile").
 * - `not`: sotto-ruoli che devono restare < 0.5 perché l'etichetta sarebbe fuorviante.
 * - `present`: devono essere > 0 (quote che dipendono dal meta: Taunt/Encore, stati con immunità).
 * - `values`: valore atteso ±0.1, solo dove è fissato dai vincoli (Rest 0.5, Toxic Spikes 0.75, schermi…).
 * - `primary`: famiglia principale attesa fra Attacco e muri (primaryFamily); l'altra è secondaria.
 * - `judgement`: riga opinabile, con la nota del perché.
 */
export interface RoleExpectation {
  species: string;
  /** Il set più comune in breve (oggetto, abilità, natura, mosse), per chi rilegge la tabella. */
  set: string;
  has?: SubRole[];
  hasAny?: SubRole[];
  not?: SubRole[];
  present?: SubRole[];
  values?: Partial<Record<SubRole, number>>;
  primary?: PrimaryFamily;
  judgement?: string;
}

export type ReferenceFormat = 'ou' | 'ubers' | 'uu' | 'gen9ou' | 'gen9uu' | 'gen9ag';

/** Cartella dei dati di ogni formato del banco. */
export const REFERENCE_DIRS: Record<ReferenceFormat, string> = {
  ou: 'gen9nationaldex', ubers: 'gen9nationaldexubers', uu: 'gen9nationaldexuu',
  gen9ou: 'gen9ou', gen9uu: 'gen9uu', gen9ag: 'gen9anythinggoes',
};

